:root{
  --atlantic:#0b2d3a;
  --deep:#061a22;
  --deep-2:#082632;
  --sea:#2f7075;
  --sea-light:#83c5bb;
  --foam:#edf5f1;
  --oyster:#f7f1e7;
  --sand:#dccbad;
  --gold:#d8b36c;
  --ink:#15343c;
  --muted:#657b7e;
  --white:#fff;
  --line:rgba(21,52,60,.13);
  --shadow:0 32px 90px rgba(4,28,36,.18);
  --radius-xl:34px;
  --radius-lg:24px;
  --radius-md:16px;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0;
  color:var(--ink);
  background:
    radial-gradient(circle at 85% 2%,rgba(131,197,187,.28),transparent 25%),
    linear-gradient(180deg,#f8f4eb 0%,#eef4ef 55%,#f8f4eb 100%);
  font-family:"DM Sans",system-ui,sans-serif;
  overflow-x:hidden;
}
button,input,textarea{font:inherit}
button{cursor:pointer}
a{color:inherit}
img,svg{display:block}
::selection{background:var(--sea-light);color:var(--deep)}
.container{width:min(1180px,calc(100% - 40px));margin-inline:auto}
.hidden{display:none}
.skip-link{position:fixed;left:16px;top:-80px;padding:12px 18px;background:white;border-radius:12px;z-index:1000}
.skip-link:focus{top:16px}
.page-noise{position:fixed;inset:0;pointer-events:none;opacity:.03;z-index:-1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E")}
.ambient{position:fixed;border-radius:50%;filter:blur(125px);pointer-events:none;opacity:.33;z-index:-2}
.ambient-one{width:430px;height:430px;background:#7cb0a7;right:-180px;top:110px}
.ambient-two{width:360px;height:360px;background:#dfc493;left:-170px;top:600px}

.site-header{position:sticky;top:0;z-index:40;background:rgba(247,241,231,.82);backdrop-filter:blur(18px);border-bottom:1px solid rgba(11,45,58,.07)}
.nav-shell{min-height:80px;display:flex;align-items:center;gap:36px}
.brand{display:inline-flex;align-items:center;gap:12px;text-decoration:none;margin-right:auto}
.brand-copy strong,.brand-copy small{display:block;line-height:1.1}
.brand-copy strong{font-size:16px;letter-spacing:-.02em}
.brand-copy small{margin-top:5px;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.16em}
.desktop-nav{display:flex;gap:28px}
.desktop-nav a,.mobile-nav a{text-decoration:none;font-size:14px;font-weight:600}
.desktop-nav a{position:relative}
.desktop-nav a:after{content:"";position:absolute;left:0;right:100%;bottom:-6px;height:1px;background:var(--sea);transition:right .25s ease}
.desktop-nav a:hover:after{right:0}
.menu-button{display:none;border:0;background:transparent;padding:8px}
.menu-button span{width:24px;height:2px;display:block;margin:5px 0;background:var(--atlantic)}
.mobile-nav{padding:8px 20px 24px}
.mobile-nav a{display:block;padding:12px 0;border-bottom:1px solid var(--line)}

.button{display:inline-flex;align-items:center;justify-content:center;min-height:52px;padding:0 24px;border:0;border-radius:999px;font-weight:700;text-decoration:none;transition:transform .2s ease,box-shadow .2s ease}
.button:hover{transform:translateY(-2px)}
.button-small{min-height:43px;padding-inline:20px;font-size:13px}
.button-light{background:var(--oyster);color:var(--atlantic);box-shadow:inset 0 0 0 1px rgba(11,45,58,.13)}
.button-gold{background:var(--gold);color:var(--deep);box-shadow:0 12px 28px rgba(216,179,108,.28)}
.button-full{width:100%}

.eyebrow{display:flex;align-items:center;gap:10px;margin:0 0 20px;color:var(--sea);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.18em}
.eyebrow span{width:28px;height:1px;background:currentColor}
.eyebrow-light{color:var(--sea-light)}

.hero{min-height:calc(100vh - 80px);padding-block:clamp(60px,8vw,110px);display:grid;grid-template-columns:.88fr 1.35fr;gap:clamp(46px,6vw,90px);align-items:center}
.hero h1,.section-heading h2,.pilot-copy h2{margin:0;font-family:"Playfair Display",Georgia,serif;font-weight:600;letter-spacing:-.045em}
.hero h1{max-width:640px;font-size:clamp(54px,6.4vw,92px);line-height:.96}
.hero h1 em{color:var(--sea)}
.hero-description{max-width:580px;margin:28px 0 30px;color:#526f72;line-height:1.75;font-size:17px}
.hero-actions{display:flex;align-items:center;gap:24px;flex-wrap:wrap}
.text-link{font-weight:700;text-decoration:none}
.text-link span{display:inline-block;transition:transform .2s ease}
.text-link:hover span{transform:translate(3px,-3px)}
.hero-outcomes{margin-top:46px;display:grid;grid-template-columns:repeat(3,1fr);gap:16px;padding-top:24px;border-top:1px solid var(--line)}
.hero-outcomes strong,.hero-outcomes span{display:block}
.hero-outcomes strong{font-size:13px}
.hero-outcomes span{margin-top:4px;color:var(--muted);font-size:12px}

.product-stage{position:relative;padding:24px;color:#e8f3f0;background:radial-gradient(circle at 75% 12%,rgba(79,133,132,.36),transparent 32%),linear-gradient(145deg,#0b3442,#061b24 70%);border:1px solid rgba(255,255,255,.12);border-radius:var(--radius-xl);box-shadow:var(--shadow)}
.product-stage:after{content:"";position:absolute;inset:1px;border-radius:inherit;pointer-events:none;box-shadow:inset 0 1px 0 rgba(255,255,255,.12)}
.stage-chrome,.location-bar,.panel-title,.caller-row,.thinking-row,.portfolio-header,.location-item,.profile-top,.visit-title{display:flex;align-items:center}
.stage-chrome{justify-content:space-between;padding-bottom:18px}
.stage-label{display:block;color:#8aa9ab;font-size:11px;text-transform:uppercase;letter-spacing:.14em}
.stage-chrome strong{display:block;margin-top:5px;font-size:19px}
.stage-controls{display:flex;align-items:center;gap:8px}
.live-chip{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;color:#bce4d7;background:rgba(112,188,163,.12);border:1px solid rgba(139,216,190,.2);border-radius:999px;font-size:11px;text-transform:uppercase;letter-spacing:.12em}
.live-chip i{width:7px;height:7px;border-radius:50%;background:#80ddb9;box-shadow:0 0 0 6px rgba(128,221,185,.1);animation:pulse 2s infinite}
.icon-button{width:34px;height:34px;border:1px solid rgba(255,255,255,.1);border-radius:50%;color:#b8cbcb;background:rgba(255,255,255,.04)}
.location-bar{gap:12px;padding:15px;margin-bottom:14px;background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.08);border-radius:16px}
.location-emblem,.mini-emblem{display:grid;place-items:center;flex:0 0 auto;border-radius:12px;background:linear-gradient(145deg,#d7b779,#a97d3f);color:var(--deep);font-weight:800}
.location-emblem{width:42px;height:42px}
.location-bar strong,.location-bar span{display:block}
.location-bar strong{font-size:13px}
.location-bar span{margin-top:4px;color:#8ba7aa;font-size:11px}
.location-chevron{margin-left:auto;border:0;color:#b8cbcb;background:transparent;font-size:20px}

.dashboard-grid{display:grid;grid-template-columns:1.18fr .82fr;gap:14px}
.panel{background:rgba(255,255,255,.055);border:1px solid rgba(255,255,255,.08);border-radius:var(--radius-md)}
.call-panel,.floor-panel{padding:17px}
.panel-title{justify-content:space-between;color:#92adaf;font-size:10px;text-transform:uppercase;letter-spacing:.12em}
.status-text{color:#f1c982}
.caller-row{gap:11px;margin:19px 0 12px}
.caller-icon{width:38px;height:38px;display:grid;place-items:center;border-radius:50%;background:rgba(214,178,110,.15);color:#f3c977}
.caller-row strong,.caller-row span{display:block}
.caller-row strong{font-size:13px}
.caller-row span{margin-top:4px;color:#78979a;font-size:10px}
.call-timer{margin-left:auto;color:#8ea7a9;font-variant-numeric:tabular-nums;font-size:11px}
.waveform{height:42px;display:flex;align-items:center;gap:3px;padding:0 6px;overflow:hidden}
.waveform span{width:3px;height:9px;border-radius:999px;background:linear-gradient(#8acbbb,#d6b26e);animation:wave 1.2s ease-in-out infinite}
.waveform span:nth-child(2n){animation-delay:-.2s}
.waveform span:nth-child(3n){animation-delay:-.45s}
.waveform span:nth-child(5n){animation-delay:-.7s}
.transcript{min-height:180px;padding-top:12px;border-top:1px solid rgba(255,255,255,.07)}
.message{margin-bottom:14px}
.message span{display:block;color:#769497;font-size:9px;text-transform:uppercase;letter-spacing:.12em}
.message p{margin:6px 0 0;padding:10px 12px;border-radius:12px;line-height:1.45;font-size:11px}
.message-ai p{background:rgba(122,187,171,.1)}
.message-guest p{background:rgba(255,255,255,.07)}
.thinking-row{justify-content:space-between;padding-top:12px;border-top:1px solid rgba(255,255,255,.07);color:#779295;font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.thinking-row>div{display:flex;align-items:center;gap:7px;color:#bdddd6}
.thinking-row i{width:6px;height:6px;border-radius:50%;background:#82d5b9;animation:pulse 1.4s infinite}
.floor-map{position:relative;height:270px;margin-top:18px;border-radius:14px;background:linear-gradient(rgba(255,255,255,.04),rgba(255,255,255,.015)),repeating-linear-gradient(0deg,transparent 0 31px,rgba(255,255,255,.018) 32px),repeating-linear-gradient(90deg,transparent 0 31px,rgba(255,255,255,.018) 32px);overflow:hidden}
.floor-map:after{content:"";position:absolute;left:0;right:0;bottom:0;height:34px;background:linear-gradient(90deg,rgba(75,135,151,.28),rgba(82,159,166,.08));border-top:1px solid rgba(128,202,207,.18)}
.water-edge{position:absolute;left:12px;bottom:10px;z-index:1;color:#77a8ad;font-size:9px;text-transform:uppercase;letter-spacing:.12em}
.table{position:absolute;left:var(--x);top:var(--y);width:43px;height:30px;display:grid;place-items:center;transform:translate(-50%,-50%);color:#b0c4c4;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:8px;font-size:9px;transition:.6s ease}
.table-round{width:34px;height:34px;border-radius:50%}
.table.reserved{color:#d9b978;border-color:rgba(217,185,120,.35);background:rgba(217,185,120,.12)}
.table.occupied{color:#7fa4a2;background:rgba(45,96,99,.38)}
.table.featured.confirmed{color:#061e25;background:#83d1b5;border-color:#9de8cf;transform:translate(-50%,-50%) scale(1.1);box-shadow:0 0 0 8px rgba(131,209,181,.08),0 0 30px rgba(131,209,181,.25)}
.legend{display:flex;justify-content:space-between;margin-top:13px;color:#718d90;font-size:8px;text-transform:uppercase;letter-spacing:.08em}
.legend span{display:flex;align-items:center;gap:5px}
.dot{width:6px;height:6px;border-radius:50%;background:#718b8c}
.reserved-dot{background:#d6b26e}
.occupied-dot{background:#35696b}
.metrics-panel{grid-column:1/-1;display:grid;grid-template-columns:repeat(3,1fr)}
.metric{padding:15px 18px;border-right:1px solid rgba(255,255,255,.07)}
.metric:last-child{border:0}
.metric span,.metric small,.metric strong{display:block}
.metric span{color:#789698;font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.metric strong{margin:5px 0;color:#f1f7f5;font-size:24px}
.metric small{color:#7aa996;font-size:9px}
.event-strip{display:flex;align-items:center;gap:12px;margin-top:14px;padding:12px 14px;border:1px solid rgba(255,255,255,.08);border-radius:14px;background:rgba(255,255,255,.04)}
.event-dot{width:8px;height:8px;border-radius:50%;background:var(--gold)}
.event-strip div{flex:1}
.event-strip small,.event-strip strong{display:block}
.event-strip small{color:#769397;font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.event-strip strong{margin-top:3px;font-size:11px}
.event-strip>span:last-child{color:#7f999c;font-size:9px}
.reservation-toast,.sms-toast{position:absolute;z-index:5;opacity:0;pointer-events:none;transition:opacity .45s ease,transform .55s cubic-bezier(.2,.8,.2,1)}
.reservation-toast{left:-40px;bottom:75px;width:315px;display:flex;align-items:center;gap:12px;padding:14px 16px;color:var(--deep);background:rgba(244,241,231,.97);border-radius:16px;box-shadow:0 20px 60px rgba(3,18,24,.28);transform:translate(-25px,15px)}
.reservation-toast.show{opacity:1;transform:translate(0,0)}
.confirmation-mark{width:34px;height:34px;display:grid;place-items:center;border-radius:50%;background:#c9e7dc;color:#235e50;font-weight:800}
.reservation-toast small,.reservation-toast strong,.reservation-toast div>span{display:block}
.reservation-toast small{color:#63807d;font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.reservation-toast strong{margin:3px 0;font-size:12px}
.reservation-toast div>span{color:#607678;font-size:10px}
.sms-toast{right:-52px;top:140px;width:235px;padding:14px;color:var(--ink);background:rgba(246,247,242,.96);border-radius:20px;box-shadow:0 22px 70px rgba(3,18,24,.3);transform:translate(30px,10px) rotate(2deg)}
.sms-toast.show{opacity:1;transform:translate(0,0) rotate(0)}
.sms-toast>div{display:flex;justify-content:space-between;color:#657a7b;font-size:9px;text-transform:uppercase;letter-spacing:.08em}
.sms-toast p{margin:10px 0 7px;font-size:10px;line-height:1.5}
.sms-toast>span{color:#4a8a75;font-size:9px}
.demo-caption{margin:12px 0 0;color:#6f8d90;font-size:8px;text-align:right}

.hospitality-statement{position:relative;padding:120px 0;color:var(--oyster);background:var(--atlantic);overflow:hidden}
.hospitality-statement:after{content:"";position:absolute;right:-12%;top:-50%;width:640px;height:640px;border-radius:50%;border:1px solid rgba(255,255,255,.08);box-shadow:inset 0 0 0 90px rgba(255,255,255,.015),inset 0 0 0 180px rgba(255,255,255,.015)}
.statement-inner{position:relative;z-index:1}
.statement-inner blockquote{max-width:940px;margin:0;font-family:"Playfair Display",Georgia,serif;font-size:clamp(38px,5.8vw,78px);line-height:1.05;letter-spacing:-.035em}
.statement-inner>p:last-child{max-width:650px;margin:35px 0 0 auto;color:#a9c0bf;font-size:17px;line-height:1.75}

.journey-section,.standard-section{padding-block:120px}
.section-heading{max-width:680px}
.section-heading h2{font-size:clamp(42px,5vw,68px);line-height:1.02}
.section-heading>p:last-child{color:var(--muted);line-height:1.75}
.section-heading-light{color:var(--oyster)}
.section-heading-light>p:last-child{color:#a5bdbc}
.journey-grid{margin-top:65px;display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--line)}
.journey-card{position:relative;padding:35px 28px 25px 0;border-right:1px solid var(--line)}
.journey-card:not(:first-child){padding-left:28px}
.journey-card:last-child{border-right:0}
.journey-number{color:#9cafae;font-size:10px;letter-spacing:.1em}
.journey-icon{width:52px;height:52px;margin:28px 0;display:grid;place-items:center;color:var(--sea);background:rgba(90,140,137,.1);border-radius:50%;font-size:20px}
.journey-card h3,.standard-card h3{font-family:"Playfair Display",Georgia,serif;font-size:22px}
.journey-card p,.standard-card p{color:var(--muted);line-height:1.65;font-size:14px}

.guest-profile-section{padding-block:120px;color:var(--oyster);background:linear-gradient(130deg,#0a303b,#071f29)}
.guest-profile-grid{display:grid;grid-template-columns:.88fr 1.12fr;gap:90px;align-items:center}
.feature-list{list-style:none;padding:0;margin:34px 0 0}
.feature-list li{display:flex;gap:12px;margin:15px 0;color:#cad8d5}
.feature-list span{color:var(--gold)}
.profile-card{padding:28px;color:var(--ink);background:var(--oyster);border-radius:28px;box-shadow:0 35px 100px rgba(0,0,0,.2)}
.profile-top{gap:14px}
.profile-avatar{width:54px;height:54px;display:grid;place-items:center;border-radius:50%;background:linear-gradient(145deg,#d9bf8d,#aa7f42);color:var(--deep);font-weight:800}
.profile-top div:nth-child(2){flex:1}
.profile-top small,.profile-top strong,.profile-top span{display:block}
.profile-top small{color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.profile-top strong{margin-top:4px;font-family:"Playfair Display",Georgia,serif;font-size:22px}
.profile-top span{margin-top:3px;color:var(--muted);font-size:10px}
.vip-chip{padding:8px 10px;border-radius:999px;color:#7b5a24!important;background:rgba(216,179,108,.18);font-size:9px!important;text-transform:uppercase;letter-spacing:.1em}
.profile-stats{display:grid;grid-template-columns:repeat(3,1fr);margin-top:24px;border-block:1px solid var(--line)}
.profile-stats div{padding:18px 8px;border-right:1px solid var(--line)}
.profile-stats div:last-child{border:0}
.profile-stats span,.profile-stats strong{display:block}
.profile-stats span{color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.profile-stats strong{margin-top:6px;font-size:12px}
.profile-note{margin-top:20px;padding:16px;border-radius:14px;background:rgba(47,112,117,.08)}
.profile-note span{color:var(--sea);font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.profile-note p{margin:7px 0 0;font-size:12px;line-height:1.6}
.visit-history{margin-top:18px}
.visit-title{justify-content:space-between;margin-bottom:8px}
.visit-title span{font-weight:700;font-size:11px}
.visit-title small{color:var(--muted);font-size:9px}
.visit-row{display:grid;grid-template-columns:70px 1fr auto;gap:12px;padding:12px 0;border-top:1px solid var(--line);align-items:center}
.visit-row span,.visit-row small{color:var(--muted);font-size:9px}
.visit-row strong{font-size:11px}

.portfolio-section{padding-block:120px;color:var(--oyster);background:linear-gradient(130deg,#061a22,#0d3440)}
.portfolio-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:90px;align-items:center}
.portfolio-card{padding:28px;color:var(--ink);background:var(--oyster);border-radius:28px;box-shadow:0 35px 100px rgba(0,0,0,.2)}
.portfolio-header{justify-content:space-between;padding-bottom:20px}
.portfolio-header small,.portfolio-header strong{display:block}
.portfolio-header small{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.12em}
.portfolio-header strong{margin-top:7px;font-family:"Playfair Display",Georgia,serif;font-size:24px}
.live-chip-light{color:#3e7868;background:rgba(89,152,129,.1);border-color:rgba(89,152,129,.18)}
.portfolio-metrics{display:grid;grid-template-columns:repeat(3,1fr);border-block:1px solid var(--line)}
.portfolio-metrics div{padding:18px 8px;border-right:1px solid var(--line)}
.portfolio-metrics div:last-child{border:0}
.portfolio-metrics span,.portfolio-metrics strong{display:block}
.portfolio-metrics span{color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.1em}
.portfolio-metrics strong{margin-top:7px;font-size:24px}
.location-list{padding-top:12px}
.location-item{width:100%;gap:12px;padding:12px;border:0;border-radius:14px;color:var(--ink);background:transparent;text-align:left}
.location-item.active{background:rgba(45,111,115,.08)}
.location-item>span:nth-child(2){flex:1}
.location-item strong,.location-item small{display:block}
.location-item strong{font-size:12px}
.location-item small{margin-top:3px;color:var(--muted);font-size:9px}
.location-item b{color:var(--sea);font-size:14px}
.mini-emblem{width:36px;height:36px;font-size:10px}
.portfolio-note{margin:13px 0 0;color:#8a9898;font-size:9px;text-align:right}

.standard-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:60px}
.standard-card{min-height:260px;padding:28px;background:rgba(255,255,255,.5);border:1px solid var(--line);border-radius:22px}
.standard-card>strong{color:var(--gold);font-size:11px;letter-spacing:.12em}
.standard-card h3{margin-top:60px;font-size:24px;line-height:1.05}
.standard-card p{font-size:13px}

.pilot-section{padding-bottom:110px}
.pilot-card{display:grid;grid-template-columns:1fr .82fr;gap:70px;padding:clamp(38px,6vw,78px);color:var(--oyster);background:var(--atlantic);border-radius:34px;box-shadow:var(--shadow)}
.pilot-copy h2{font-size:clamp(40px,5vw,66px);line-height:1.02}
.pilot-copy>p:not(.eyebrow):not(.contact-line){color:#a9c0bf;line-height:1.7}
.pilot-steps{display:flex;flex-wrap:wrap;gap:8px;margin:28px 0}
.pilot-steps span{padding:9px 12px;color:#bcd0ce;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.08);border-radius:999px;font-size:10px}
.contact-line{color:#9cb7b5;font-size:12px}
.contact-line a{color:var(--oyster)}
.pilot-form{padding:25px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);border-radius:22px}
.pilot-form label{display:block;margin-bottom:14px;color:#b9cecc;font-size:11px}
.pilot-form input,.pilot-form textarea{width:100%;margin-top:7px;padding:13px 14px;color:white;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:12px;outline:none}
.pilot-form input:focus,.pilot-form textarea:focus{border-color:var(--sea-light);box-shadow:0 0 0 3px rgba(155,198,190,.1)}
.pilot-form textarea{resize:vertical}
.pilot-form ::placeholder{color:#7e999b}
.form-note{color:#799496;font-size:9px;line-height:1.5}

.site-footer{padding:50px 0;background:#061820;color:#c6d5d2}
.footer-grid{display:grid;grid-template-columns:1fr auto;gap:25px;align-items:center}
.footer-brand strong{color:var(--oyster)}
.footer-brand small{color:#719092}
.footer-grid>p{color:#749295}
.footer-links{display:flex;gap:24px;justify-content:flex-end}
.footer-links a{color:#9bb2b1;text-decoration:none;font-size:12px}
.footer-grid>small{color:#638082;font-size:10px}

.reveal{opacity:0;transform:translateY(28px);transition:opacity .8s ease,transform .8s ease}
.reveal.visible{opacity:1;transform:translateY(0)}
@keyframes pulse{0%,100%{opacity:1}50%{opacity:.35}}
@keyframes wave{0%,100%{height:8px;opacity:.45}50%{height:34px;opacity:1}}

@media (max-width:1050px){
  .hero{grid-template-columns:1fr;padding-top:70px}
  .hero-copy{max-width:790px}
  .product-stage{width:min(760px,100%);margin-inline:auto}
  .guest-profile-grid,.portfolio-grid{gap:50px}
}
@media (max-width:820px){
  .desktop-nav,.nav-shell>.button{display:none}
  .menu-button{display:block}
  .hero{padding-block:60px 90px}
  .hero h1{font-size:clamp(50px,13vw,74px)}
  .journey-grid,.standard-grid{grid-template-columns:repeat(2,1fr)}
  .journey-card:nth-child(2){border-right:0}
  .guest-profile-grid,.portfolio-grid,.pilot-card{grid-template-columns:1fr}
  .pilot-card{gap:45px}
}
@media (max-width:620px){
  .container{width:min(100% - 26px,1180px)}
  .nav-shell{min-height:70px}
  .hero{min-height:auto}
  .hero h1{font-size:48px}
  .hero-outcomes{grid-template-columns:1fr}
  .dashboard-grid{grid-template-columns:1fr}
  .metrics-panel{grid-column:auto;grid-template-columns:1fr}
  .metric{border-right:0;border-bottom:1px solid rgba(255,255,255,.07)}
  .floor-map{height:230px}
  .reservation-toast{left:10px;bottom:15px;width:calc(100% - 20px)}
  .sms-toast{right:8px;top:185px}
  .hospitality-statement,.journey-section,.standard-section,.guest-profile-section,.portfolio-section{padding-block:85px}
  .journey-grid,.standard-grid{grid-template-columns:1fr}
  .journey-card,.journey-card:not(:first-child){padding:28px 0;border-right:0;border-bottom:1px solid var(--line)}
  .journey-card:last-child{border-bottom:0}
  .standard-card{min-height:220px}
  .standard-card h3{margin-top:45px}
  .profile-stats{grid-template-columns:1fr}
  .profile-stats div{border-right:0;border-bottom:1px solid var(--line)}
  .visit-row{grid-template-columns:62px 1fr}
  .visit-row small{grid-column:2}
  .portfolio-card{padding:18px}
  .portfolio-metrics strong{font-size:19px}
  .pilot-card{padding:28px 18px;border-radius:24px}
  .footer-grid{grid-template-columns:1fr}
  .footer-links{justify-content:flex-start}
}
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}
}

.evening-service{padding:120px 0;color:var(--oyster);background:radial-gradient(circle at 85% 10%,rgba(216,179,108,.12),transparent 30%),linear-gradient(145deg,#061820,#0b313d)}
