.mission-feed-header small{display:block;color:#62c9c1;margin-bottom:.2rem;text-transform:uppercase;letter-spacing:.09em;font-size:.72rem}.mission-feed-header strong{font-size:1rem}.mission-feed-header time{color:rgba(255,255,255,.5);font-size:.85rem}
.mission-event-feed{height:520px;overflow:auto;padding:1.15rem .25rem .5rem;scrollbar-width:thin}
