@keyframes missionPulse{50%{opacity:.55;box-shadow:0 0 0 9px rgba(98,211,163,0)}}@keyframes missionEnter{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:none}}
@media(max-width:1050px){.mission-control-shell{grid-template-columns:190px minmax(0,1fr)}.mission-state-panel{grid-column:1/-1;border-left:0;border-top:1px solid rgba(255,255,255,.08);display:grid;grid-template-columns:220px 1fr 1fr;gap:1.25rem}.mission-state-panel dl{display:grid;grid-template-columns:repeat(3,1fr);gap:0 1rem;margin:0}.mission-brief{margin:0}}
