/* V21 — Production Readiness */
.production-readiness { padding: 110px 0; position: relative; }
.production-readiness::before { content:""; position:absolute; inset:8% 0 auto; height:420px; background:radial-gradient(circle at 75% 20%,rgba(75,168,255,.12),transparent 50%); pointer-events:none; }
.production-summary-grid { display:grid; grid-template-columns:1.65fr .8fr; gap:20px; margin-top:34px; }
.production-hero-card,.production-panel,.production-workspace { background:linear-gradient(145deg,rgba(12,24,41,.96),rgba(7,17,30,.94)); border:1px solid rgba(154,203,255,.16); border-radius:24px; box-shadow:0 28px 80px rgba(0,0,0,.24); }
.production-hero-card,.production-panel { padding:26px; }
.production-card-head,.production-panel-title { display:flex; align-items:flex-start; justify-content:space-between; gap:20px; }
.production-card-head small,.production-panel-title small { color:#8fa9c5; text-transform:uppercase; letter-spacing:.12em; font-size:.68rem; }
.production-card-head h3,.production-panel-title h3 { margin:5px 0 0; font-size:1.35rem; }
.production-status { border-radius:999px; padding:7px 11px; font-size:.72rem; font-weight:800; }
.production-status.ready { color:#86f3c2; background:rgba(36,204,133,.12); border:1px solid rgba(36,204,133,.3); }
.production-status.watch { color:#ffd27e; background:rgba(255,175,55,.12); border:1px solid rgba(255,175,55,.3); }
.production-kpis { display:grid; grid-template-columns:repeat(4,1fr); gap:12px; margin:28px 0 20px; }
.production-kpis div { padding:16px; border-radius:16px; background:rgba(255,255,255,.035); border:1px solid rgba(255,255,255,.07); }
.production-kpis strong { display:block; font-size:1.55rem; }
.production-kpis span { display:block; color:#89a3bd; font-size:.72rem; margin-top:4px; }
.production-actions { display:flex; gap:10px; flex-wrap:wrap; margin-top:22px; }
.production-live-dot { width:10px; height:10px; margin-top:8px; border-radius:50%; background:#5be0a5; box-shadow:0 0 0 7px rgba(91,224,165,.08); }
.production-mode-toggle { display:grid; grid-template-columns:1fr 1fr; gap:5px; padding:5px; border:1px solid rgba(255,255,255,.08); border-radius:13px; margin:26px 0 16px; }
.production-mode-toggle button,.production-tabs button { border:0; color:#8da7c1; background:transparent; cursor:pointer; }
.production-mode-toggle button { padding:11px; border-radius:9px; font-weight:800; }
.production-mode-toggle button.active { color:#eaf7ff; background:rgba(77,167,255,.16); }
.production-text-button { color:#7ec5ff; border:0; background:transparent; padding:0; margin-top:18px; cursor:pointer; }
.production-tabs { display:flex; gap:6px; overflow:auto; margin-top:22px; padding:6px; border:1px solid rgba(154,203,255,.12); border-radius:16px; background:rgba(5,14,25,.7); }
.production-tabs button { white-space:nowrap; padding:12px 16px; border-radius:11px; font-weight:750; }
.production-tabs button.active { color:#fff; background:rgba(72,156,242,.18); }
.production-workspace { margin-top:14px; padding:28px; min-height:430px; }
.production-tab-panel { display:none; }
.production-tab-panel.active { display:block; animation:productionPanelIn .28s ease; }
@keyframes productionPanelIn { from{opacity:0;transform:translateY(7px)} to{opacity:1;transform:none} }
.production-panel-title { align-items:center; margin-bottom:22px; }
.production-panel-title > span { color:#8ea9c3; font-size:.8rem; }
.production-progress { height:8px; border-radius:99px; background:rgba(255,255,255,.06); overflow:hidden; }
.production-progress i { display:block; height:100%; border-radius:inherit; background:linear-gradient(90deg,#4c9eef,#69dfc0); transition:width .5s ease; }
.production-step-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; margin:20px 0 24px; }
.production-step-grid button { display:flex; gap:11px; align-items:center; text-align:left; padding:14px; color:#d6e6f5; background:rgba(255,255,255,.025); border:1px solid rgba(255,255,255,.07); border-radius:14px; }
.production-step-grid button b { display:grid; place-items:center; flex:0 0 30px; height:30px; border-radius:50%; background:rgba(255,255,255,.08); }
.production-step-grid button.complete b { color:#09261d; background:#63deb1; }
.production-step-grid span { flex:1; }
.production-step-grid strong,.production-step-grid small,.production-step-grid em { display:block; }
.production-step-grid small { color:#819bb4; margin-top:2px; font-size:.67rem; }
.production-step-grid em { color:#72c6ff; font-style:normal; font-size:.65rem; }
.production-form-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:14px; margin:20px 0; }
.production-form-grid label { color:#91abc4; font-size:.72rem; font-weight:750; }
.production-form-grid input,.production-form-grid select { width:100%; margin-top:7px; padding:12px 13px; color:#e9f5ff; background:#091522; border:1px solid rgba(155,205,255,.15); border-radius:11px; }
.production-form-grid label > small { float:right; margin-top:-31px; margin-right:12px; color:#718ba4; pointer-events:none; }
.production-user-list { display:grid; gap:9px; }
.production-user-list article { display:grid; grid-template-columns:42px 1fr 190px 80px; gap:13px; align-items:center; padding:13px; border:1px solid rgba(255,255,255,.07); border-radius:14px; background:rgba(255,255,255,.025); }
.production-user-list article > span { display:grid; place-items:center; height:42px; border-radius:12px; background:rgba(76,158,239,.14); color:#79c7ff; font-weight:850; }
.production-user-list strong,.production-user-list small { display:block; }
.production-user-list small { color:#809ab3; margin-top:2px; }
.production-user-list select { color:#dbeafa; background:#081522; border:1px solid rgba(255,255,255,.1); padding:9px; border-radius:9px; }
.production-user-list em { font-size:.68rem; font-style:normal; color:#72e1b2; }
.production-user-list em.invited { color:#ffd07a; }
.production-feature-grid { display:grid; grid-template-columns:repeat(2,1fr); gap:11px; }
.production-feature-card { display:grid; grid-template-columns:1fr auto; align-items:center; gap:15px; padding:17px; border:1px solid rgba(255,255,255,.07); border-radius:15px; background:rgba(255,255,255,.025); cursor:pointer; position:relative; }
.production-feature-card strong,.production-feature-card small { display:block; }
.production-feature-card small { color:#809ab3; margin-top:4px; font-size:.68rem; }
.production-feature-card input { position:absolute; opacity:0; }
.production-feature-card i { width:42px; height:23px; border-radius:99px; background:#26394b; position:relative; transition:.2s; }
.production-feature-card i::after { content:""; position:absolute; width:17px; height:17px; top:3px; left:3px; border-radius:50%; background:#a8bbca; transition:.2s; }
.production-feature-card input:checked + i { background:#328bdc; }
.production-feature-card input:checked + i::after { transform:translateX(19px); background:#fff; }
.production-health-grid { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; }
