/* =========================================================
   V22.1 — Visual Clarity & Accessibility
   High-contrast overrides for Blue Current Live
   ========================================================= */

:root {
  --bc-live-panel: #0b2633;
  --bc-live-panel-deep: #071d28;
  --bc-live-surface: #123442;
  --bc-live-surface-hover: #183f50;
  --bc-live-border: rgba(177, 220, 240, 0.22);
  --bc-live-text: #f7fbff;
  --bc-live-muted: #bed0dc;
  --bc-live-soft: #91aab9;
  --bc-live-gold: #e5b85f;
  --bc-live-green: #7be2ae;
}

/* Reduce the bright background wash behind the dashboard. */
.live-command-center {
  position: relative;
  isolation: isolate;
}

.live-command-center::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: 2rem -8vw auto;
  height: 34rem;
  opacity: 0.22;
  filter: blur(110px);
  background:
    radial-gradient(circle at 16% 28%, rgba(82, 176, 204, 0.3), transparent 46%),
    radial-gradient(circle at 84% 16%, rgba(75, 173, 150, 0.2), transparent 42%);
  pointer-events: none;
}

/* Keep the light section heading readable without overpowering the interface. */
.live-command-head h2 {
  color: #173746;
  font-weight: 800;
  letter-spacing: -0.025em;
}

.live-command-head > div > p:not(.eyebrow) {
  color: #294958;
  font-weight: 500;
  line-height: 1.55;
}

.live-command-head .eyebrow {
  color: #217588;
  font-weight: 800;
}

/* Health ring */
.live-health-ring {
  background:
    radial-gradient(circle at center, #0b3442 57%, transparent 58%),
    conic-gradient(var(--bc-live-gold) 0 94%, rgba(20, 55, 69, 0.16) 94%);
  border: 1px solid rgba(229, 184, 95, 0.4);
  box-shadow: 0 24px 64px rgba(3, 20, 27, 0.28);
}

.live-health-ring strong {
  color: #ffffff;
  text-shadow: 0 1px 12px rgba(0, 0, 0, 0.28);
}

.live-health-ring span {
  color: #d6e7ef;
  font-weight: 700;
}

/* KPI cards */
.live-kpi-grid button {
  color: var(--bc-live-text);
  background: linear-gradient(145deg, #123441, #0c2a36);
  border-color: var(--bc-live-border);
  box-shadow: 0 14px 34px rgba(3, 19, 27, 0.16);
}

.live-kpi-grid button:hover,
.live-kpi-grid button:focus-visible {
  color: #ffffff;
  background: linear-gradient(145deg, #18404f, #103441);
  border-color: rgba(229, 184, 95, 0.68);
  box-shadow: 0 18px 42px rgba(3, 19, 27, 0.24);
}

.live-kpi-grid small,
.live-action-card > small {
  color: var(--bc-live-gold);
  font-weight: 800;
}

.live-kpi-grid strong {
  color: #ffffff;
  font-size: clamp(2.25rem, 3.1vw, 3rem);
  font-weight: 850;
  line-height: 1;
  letter-spacing: -0.035em;
  text-shadow: 0 2px 16px rgba(0, 0, 0, 0.18);
}

.live-kpi-grid span {
  color: var(--bc-live-muted);
  font-size: 0.83rem;
  font-weight: 600;
}

/* Main command-center panels */
.live-copilot-card,
.live-timeline-card,
.connector-card,
.live-action-card {
  color: var(--bc-live-text);
  background: linear-gradient(145deg, var(--bc-live-panel), var(--bc-live-panel-deep));
  border-color: var(--bc-live-border);
  box-shadow: 0 24px 62px rgba(3, 18, 24, 0.28);
}

.live-panel-head small {
  color: var(--bc-live-gold);
  font-weight: 800;
}

.live-panel-head h3,
.live-copilot-card h3,
.live-timeline-card h3,
.connector-card h3,
.live-action-card h3 {
  color: #ffffff;
}

.live-status {
  color: #9de8bd;
  font-weight: 750;
}

/* Copilot */
.copilot-answer {
  color: var(--bc-live-text);
  background: #102f3d;
  border-color: rgba(176, 220, 239, 0.18);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.025);
}

.copilot-answer small {
  color: var(--bc-live-gold);
  font-weight: 800;
}

.copilot-answer p {
  color: #e6f0f5;
  font-weight: 500;
}

.copilot-prompts button,
.connector-card button,
.live-action-card button,
.copilot-form button {
  color: #fff1d2;
  background: rgba(229, 184, 95, 0.13);
  border-color: rgba(229, 184, 95, 0.48);
  font-weight: 750;
}

.copilot-prompts button:hover,
.connector-card button:hover,
.live-action-card button:hover,
.copilot-form button:hover {
  color: #09202a;
  background: var(--bc-live-gold);
  border-color: var(--bc-live-gold);
}

/* Inputs and search */
.copilot-form input,
.live-panel-head input {
  color: #ffffff;
  caret-color: #ffffff;
  background: #102f3d;
  border-color: rgba(180, 220, 238, 0.24);
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.16);
}

.copilot-form input::placeholder,
.live-panel-head input::placeholder {
  color: #a9bdc9;
  opacity: 1;
}

.copilot-form input:focus,
.live-panel-head input:focus {
  outline: 2px solid rgba(229, 184, 95, 0.5);
  outline-offset: 2px;
  border-color: var(--bc-live-gold);
}

/* Operational timeline */
.live-event {
  color: var(--bc-live-text);
  background: #102f3d;
  border: 1px solid rgba(176, 220, 239, 0.1);
}

.live-event:hover {
  background: var(--bc-live-surface-hover);
  border-color: rgba(176, 220, 239, 0.22);
}

.live-event time {
  color: #f0c66f;
  font-weight: 800;
}

.live-event strong {
  color: #ffffff;
}

.live-event small,
.live-event-empty {
  color: var(--bc-live-muted);
}

/* Connector cards */
.connector-grid > div {
  color: var(--bc-live-text);
  background: #102f3d;
  border-color: rgba(176, 220, 239, 0.13);
}

.connector-grid > div:hover {
  background: var(--bc-live-surface-hover);
  border-color: rgba(176, 220, 239, 0.24);
}

.connector-grid strong,
.connector-grid span {
  color: #ffffff;
}

.connector-grid small {
  color: var(--bc-live-muted);
}

.connector-grid b {
  color: #f0c66f;
}

/* Action panel copy */
.live-action-card p {
  color: #c9dae4;
}

/* Scrollbars inside dark operational panels */
.live-event-stream {
  scrollbar-color: #7696a7 #0b2531;
  scrollbar-width: thin;
}

.live-event-stream::-webkit-scrollbar {
  width: 10px;
}

.live-event-stream::-webkit-scrollbar-track {
  background: #0b2531;
  border-radius: 999px;
}

.live-event-stream::-webkit-scrollbar-thumb {
  background: #7696a7;
  border: 2px solid #0b2531;
  border-radius: 999px;
}

/* Keyboard visibility */
.live-command-center button:focus-visible,
.live-command-center input:focus-visible {
  outline: 3px solid rgba(229, 184, 95, 0.62);
  outline-offset: 3px;
}

/* Small-screen clarity */
@media (max-width: 620px) {
  .live-kpi-grid strong {
    font-size: 2.35rem;
  }

  .live-kpi-grid button,
  .live-copilot-card,
  .live-timeline-card,
  .connector-card,
  .live-action-card {
    border-color: rgba(177, 220, 240, 0.25);
  }
}


