/* V23.0.1 — Stabilization and startup diagnostics */
.auth-overlay {
  visibility: hidden;
  opacity: 0;
  transition: opacity .18s ease;
}

.auth-overlay.open {
  visibility: visible;
  opacity: 1;
}

.startup-diagnostics {
  position: fixed;
  z-index: 11000;
  right: 16px;
  bottom: 16px;
  width: min(310px, calc(100vw - 32px));
  color: #eaf7ff;
  font-family: "DM Sans", sans-serif;
}

.startup-diagnostics > button {
  width: 100%;
  display: grid;
  grid-template-columns: 10px auto 1fr;
  align-items: center;
  gap: 9px;
  padding: 11px 13px;
  color: #eaf7ff;
  text-align: left;
  background: rgba(6, 22, 32, .96);
  border: 1px solid rgba(145, 205, 234, .22);
  border-radius: 13px;
  box-shadow: 0 18px 48px rgba(0, 0, 0, .3);
  cursor: pointer;
}

.startup-diagnostics > button strong {
  font-size: .72rem;
}

.startup-diagnostics > button small {
  color: #96afbe;
  text-align: right;
  font-size: .64rem;
}

#startupDiagnosticsDot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #e5b85f;
  box-shadow: 0 0 0 5px rgba(229, 184, 95, .09);
}

#startupDiagnosticsDot.ok {
  background: #72dfa9;
  box-shadow: 0 0 0 5px rgba(114, 223, 169, .09);
}

.startup-diagnostics-panel {
  display: none;
  margin-top: 7px;
  padding: 13px;
  background: rgba(6, 22, 32, .98);
  border: 1px solid rgba(145, 205, 234, .18);
  border-radius: 13px;
  box-shadow: 0 22px 55px rgba(0, 0, 0, .34);
}

.startup-diagnostics-panel.open {
