er-radius:15px;background:rgba(255,255,255,.055);cursor:pointer}.manager-action-list input{grid-row:1/3;margin-top:2px;accent-color:#d6b26e}.manager-action-list span{font-size:11px;font-weight:700}.manager-action-list small{margin-top:4px;color:#8ea8a8;font-size:8px}.manager-action-list label.is-complete{opacity:.55}.manager-action-list label.is-complete span{text-decoration:line-through}\n@media(max-width:980px){.manager-brief-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.manager-action-list{grid-template-columns:1fr}.readiness-panel{grid-template-columns:1fr}.readiness-signals{justify-content:flex-start}}\n@media(max-width:680px){.command-center-section{padding:85px 0 70px}.command-center-topbar{align-items:flex-start;flex-direction:column}.command-center-actions{width:100%;justify-content:space-between}.manager-brief-grid{grid-template-columns:1fr}.brief-card{min-height:auto}.readiness-panel{padding:18px}.manager-actions-heading{align-items:flex-start;flex-direction:column}}\n

