/* V34.6.6 — Global Readability System
   Eliminates washed-out backend surfaces and low-opacity operational content. */
.app-high-contrast{
  --bc-readable-bg:#071b25;
  --bc-readable-surface:#0d2b36;
  --bc-readable-surface-2:#123642;
  --bc-readable-surface-3:#173f4b;
  --bc-readable-text:#f7fbfc;
  --bc-readable-secondary:#d2e1e5;
  --bc-readable-muted:#abc1c8;
  --bc-readable-border:rgba(211,234,239,.25);
  --bc-readable-border-strong:rgba(211,234,239,.42);
}

/* Operational content must never remain faded because an observer/reveal callback was missed. */
.app-high-contrast .reveal,
.app-high-contrast .reveal.visible,
.app-high-contrast .brief-card.is-loading,
.app-high-contrast [class*="is-loading"]{
  opacity:1!important;
  transform:none!important;
  filter:none!important;
}

/* Prevent translucent overlays and decorative gradients from bleaching the application. */
.app-high-contrast .command-center-section,
.app-high-contrast .manager-shift-brief,
.app-high-contrast .readiness-panel,
.app-high-contrast .readiness-breakdown,
.app-high-contrast .manager-actions-panel{
  color:var(--bc-readable-text)!important;
  background:var(--bc-readable-bg)!important;
  background-image:none!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}

.app-high-contrast .command-center-section::before,
.app-high-contrast .command-center-section::after,
.app-high-contrast .manager-shift-brief::before,
.app-high-contrast .manager-shift-brief::after{
  opacity:.08!important;
  pointer-events:none;
}

/* Command Center shell and Manager Brief become solid, high-contrast operational surfaces. */
.app-high-contrast .manager-shift-brief{
  border:1px solid var(--bc-readable-border-strong)!important;
  border-radius:24px!important;
  box-shadow:0 28px 80px rgba(0,0,0,.34)!important;
  padding:28px!important;
}
.app-high-contrast .manager-shift-brief-grid,
.app-high-contrast .manager-shift-kpis{
  gap:14px!important;
}
.app-high-contrast .manager-shift-summary,
.app-high-contrast .manager-shift-kpis,
.app-high-contrast .manager-shift-handoff,
.app-high-contrast .manager-shift-brief-footer,
.app-high-contrast .readiness-panel,
.app-high-contrast .readiness-breakdown,
.app-high-contrast .manager-actions-panel{
  background:var(--bc-readable-surface)!important;
  border:1px solid var(--bc-readable-border)!important;
  color:var(--bc-readable-text)!important;
  box-shadow:none!important;
  opacity:1!important;
}
.app-high-contrast .manager-shift-kpis>div,
.app-high-contrast .readiness-component,
.app-high-contrast .manager-action-list label{
  background:var(--bc-readable-surface-2)!important;
  border:1px solid var(--bc-readable-border)!important;
  color:var(--bc-readable-text)!important;
  opacity:1!important;
}

/* Explicit typography hierarchy for the formerly washed-out area. */
.app-high-contrast .manager-shift-brief :is(h1,h2,h3,h4,strong,b),
.app-high-contrast .readiness-panel :is(h1,h2,h3,h4,strong,b),
.app-high-contrast .readiness-breakdown :is(h1,h2,h3,h4,strong,b),
.app-high-contrast .manager-actions-panel :is(h1,h2,h3,h4,strong,b){
  color:var(--bc-readable-text)!important;
  opacity:1!important;
  text-shadow:none!important;
}
.app-high-contrast .manager-shift-brief :is(p,li,label,span),
.app-high-contrast .readiness-panel :is(p,li,label,span),
.app-high-contrast .readiness-breakdown :is(p,li,label,span),
.app-high-contrast .manager-actions-panel :is(p,li,label,span){
  color:var(--bc-readable-secondary)!important;
  opacity:1!important;
}
.app-high-contrast .manager-shift-brief :is(small,time),
.app-high-contrast .readiness-panel :is(small,time),
.app-high-contrast .readiness-breakdown :is(small,time),
.app-high-contrast .manager-actions-panel :is(small,time){
  color:var(--bc-readable-muted)!important;
  opacity:1!important;
}
.app-high-contrast .manager-shift-brief-topline h3{
  font-size:clamp(1.65rem,2.4vw,2.35rem)!important;
  line-height:1.12!important;
  font-weight:800!important;
}
.app-high-contrast .manager-shift-summary-heading strong,
.app-high-contrast .manager-shift-handoff-heading strong{
  font-size:1.15rem!important;
  font-weight:850!important;
}
.app-high-contrast .manager-shift-priority-list,
.app-high-contrast #managerShiftPriorityList{
  font-size:1rem!important;
  line-height:1.5!important;
}
.app-high-contrast #managerShiftPriorityList li{
  padding:13px 0!important;
  border-color:var(--bc-readable-border)!important;
  color:var(--bc-readable-secondary)!important;
}
.app-high-contrast .manager-shift-kpis strong{
  color:#fff!important;
  font-size:1.65rem!important;
  line-height:1.1!important;
}
.app-high-contrast .manager-shift-kpis small{
  font-size:.76rem!important;
  font-weight:800!important;
  letter-spacing:.08em!important;
}
.app-high-contrast .manager-shift-kpis span,
.app-high-contrast .manager-shift-handoff p,
.app-high-contrast .manager-shift-brief-footer p{
  color:var(--bc-readable-secondary)!important;
  font-size:.95rem!important;
  line-height:1.6!important;
}
.app-high-contrast .manager-shift-brief-footer{
  margin-top:18px!important;
  padding:22px!important;
}
.app-high-contrast #managerShiftStart{
  min-height:50px!important;
  padding:0 24px!important;
  border:1px solid #e7c879!important;
  background:#d9ad4f!important;
  color:#112832!important;
  font-size:1rem!important;
  font-weight:900!important;
  box-shadow:0 10px 26px rgba(217,173,79,.2)!important;
}

/* Light cards must retain dark type; dark cards retain light type. */
.app-high-contrast .brief-card:not(.brief-ai){
  background:#f7faf9!important;
  border-color:rgba(16,43,52,.2)!important;
  color:#102b34!important;
  opacity:1!important;
}
.app-high-contrast .brief-card:not(.brief-ai) :is(h1,h2,h3,h4,strong,b,blockquote,dd){color:#102b34!important}
.app-high-contrast .brief-card:not(.brief-ai) :is(p,li,label,dt,span){color:#405e65!important}
.app-high-contrast .brief-card:not(.brief-ai) :is(small,time,.muted,[class*="-muted"],[class*="-updated"]){color:#607b82!important}
.app-high-contrast .brief-ai{
  background:var(--bc-readable-surface)!important;
  border-color:var(--bc-readable-border)!important;
  color:var(--bc-readable-text)!important;
}

/* Global operational typography floor: labels should not be microscopic. */
.app-high-contrast :is(
  .command-center-section,.mission-control-shell,.time-machine-shell,
  .portfolio-command-shell,.guest-journey-live-shell,.concierge-shell,
  .analytics-shell,.exec-shell,.host-app,.twin-app,.evening-dashboard,
  .autonomous-operations-section,.ai-orchestration-center,
  .operational-digital-twin-center,.portfolio-intelligence-center,
  .ai-brain-shell,.executive-decision-center
) :is(p,li,label,button,input,select,textarea){
  font-size:max(.82rem,13px);
  line-height:1.45;
}
.app-high-contrast :is(
  .command-center-section,.mission-control-shell,.time-machine-shell,
  .portfolio-command-shell,.guest-journey-live-shell,.concierge-shell,
  .analytics-shell,.exec-shell,.host-app,.twin-app,.evening-dashboard,
  .autonomous-operations-section,.ai-orchestration-center,
  .operational-digital-twin-center,.portfolio-intelligence-center,
  .ai-brain-shell,.executive-decision-center
) :is(small,time,dt){
  font-size:max(.72rem,11px);
  line-height:1.4;
}

/* Completed and inactive content remains readable instead of disappearing. */
.app-high-contrast :is(.is-complete,.is-past,.is-inactive):not(button):not([hidden]){
  opacity:.86!important;
}
.app-high-contrast button:disabled,
.app-high-contrast [aria-disabled="true"]{
  opacity:.78!important;
  color:#d0dde1!important;
  border-color:rgba(211,234,239,.3)!important;
}

/* Top navigation remains solid and readable while scrolling. */
.app-high-contrast .site-header{
  background:#f7f3ea!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
  box-shadow:0 3px 18px rgba(3,20,28,.12)!important;
}
.app-high-contrast .site-header :is(a,button,strong,span){
  opacity:1!important;
}

@media(max-width:760px){
  .app-high-contrast .manager-shift-brief{padding:18px!important}
  .app-high-contrast .manager-shift-kpis{grid-template-columns:1fr 1fr!important}
  .app-high-contrast .manager-shift-brief-footer{align-items:stretch!important}
  .app-high-contrast #managerShiftStart{width:100%!important}
