\n\n/* V35.2 Executive Briefing */\n.executive-briefing-center{margin:24px 0;padding:26px;border:1px solid #334155;border-radius:24px;background:#071321;color:#f8fafc;box-shadow:0 22px 55px rgba(2,6,23,.34)}\n.executive-briefing-header{display:flex;justify-content:space-between;gap:20px;align-items:center}.executive-briefing-header>div:first-child{display:grid;gap:5px}.executive-briefing-header small,.executive-briefing-title small,.executive-briefing-next small{color:#7dd3fc;font-weight:900;letter-spacing:.08em;text-transform:uppercase}.executive-briefing-header strong{font-size:clamp(1.55rem,2.5vw,2.3rem);line-height:1.08}.executive-briefing-header span{color:#cbd5e1;font-weight:650}.executive-briefing-actions{display:flex;gap:10px;flex-wrap:wrap}.executive-briefing-actions button,.executive-briefing-next button{border:1px solid #38bdf8;border-radius:13px;background:#075985;color:#fff;font-size:.94rem;font-weight:900;padding:12px 16px;cursor:pointer}.executive-briefing-actions button:hover,.executive-briefing-next button:hover{background:#0369a1}.executive-briefing-next button:disabled{opacity:.55;cursor:not-allowed}\n.executive-briefing-lead{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(420px,.85fr);gap:18px;margin:22px 0}.executive-briefing-lead>div{display:grid;gap:8px;padding:22px;border:1px solid rgba(56,189,248,.32);border-radius:19px;background:#0b2034}.executive-briefing-lead>div span{justify-self:start;padding:6px 10px;border-radius:999px;background:#164e63;color:#dff8ff;font-size:.78rem;font-weight:900;text-transform:uppercase}.executive-briefing-lead>div strong{font-size:clamp(1.35rem,2.2vw,2rem);line-height:1.15}.executive-briefing-lead>div p{margin:0;color:#d7e4ef;font-size:1rem;line-height:1.65}.executive-briefing-lead dl{margin:0;display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.executive-briefing-lead dl div{padding:16px;border:1px solid #334155;border-radius:15px;background:#111c2e}.executive-briefing-lead dt{color:#aebed0;font-size:.74rem;font-weight:900;text-transform:uppercase}.executive-briefing-lead dd{margin:6px 0 0;color:#fff;font-size:1.6rem;font-weight:900}\n.executive-briefing-questions{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin-bottom:18px}.executive-briefing-questions article{padding:15px;border:1px solid #334155;border-radius:15px;background:#101b2d;display:grid;gap:6px}.executive-briefing-questions small{color:#93c5fd;font-weight:850}.executive-briefing-questions strong{color:#fff;line-height:1.4}\n.executive-briefing-grid{display:grid;grid-template-columns:1.1fr .95fr .85fr;gap:16px}.executive-briefing-grid>section{padding:18px;border:1px solid #334155;border-radius:18px;background:#0d192a}.executive-briefing-title{display:grid;gap:3px;margin-bottom:13px}.executive-briefing-title strong{font-size:1.08rem}.executive-briefing-priorities,.executive-briefing-risks,.executive-briefing-wins{display:grid;gap:10px}.executive-briefing-priority{display:grid;grid-template-columns:30px 1fr auto;gap:11px;align-items:center;padding:14px;border:1px solid #3b4a60;border-radius:14px;background:#142238}.executive-briefing-priority>span{display:grid;place-items:center;width:29px;height:29px;border-radius:50%;background:#075985;color:#fff;font-weight:900}.executive-briefing-priority div,.executive-briefing-risk div,.executive-briefing-wins article{display:grid;gap:3px}.executive-briefing-priority small,.executive-briefing-risk small,.executive-briefing-wins small{color:#bae6fd;font-weight:750}.executive-briefing-priority p,.executive-briefing-risk p,.executive-briefing-wins p{margin:0;color:#d5e3ef;line-height:1.45}.executive-briefing-priority>b{display:grid;text-align:right;color:#a7f3d0;white-space:nowrap}.executive-briefing-priority>b i{color:#fde68a;font-style:normal;font-size:.82rem}.executive-briefing-risk{display:grid;grid-template-columns:auto 1fr;gap:10px;padding:13px;border:1px solid #3b4a60;border-radius:14px;background:#142238}.executive-briefing-ri