/* V35.4.0 — Performance Learning, Calibration & Pilot Hardening */
.performance-learning-center {
  margin: 26px 0;
  padding: 24px;
  border: 1px solid rgba(94, 234, 212, .32);
  border-radius: 24px;
  background: linear-gradient(145deg, rgba(8, 21, 38, .99), rgba(12, 31, 52, .99));
  color: #f8fafc;
  box-shadow: 0 24px 60px rgba(2, 8, 23, .34);
}
.performance-learning-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 18px;
  align-items: center;
}
.performance-learning-header > div:first-child {
  display: grid;
  gap: 5px;
}
.performance-learning-header small,
.performance-learning-title small,
.performance-learning-kpis small,
.performance-learning-score small {
  color: #9fb3c8;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}
.performance-learning-header strong {
  color: #ffffff;
  font-size: clamp(1.35rem, 2vw, 2rem);
  line-height: 1.18;
}
.performance-learning-header span,
.performance-learning-headline {
  color: #d4deea;
}
.performance-learning-score {
  min-width: 126px;
  padding: 14px 18px;
  border: 1px solid rgba(94, 234, 212, .28);
  border-radius: 18px;
  background: #0b1c30;
  text-align: center;
  display: grid;
  gap: 3px;
}
.performance-learning-score strong {
  font-size: 2.2rem;
  color: #5eead4;
}
.performance-learning-score span {
  font-weight: 850;
  text-transform: capitalize;
  color: #dffcf7;
}
.performance-learning-header button {
  min-height: 44px;
  padding: 0 18px;
  border: 1px solid #5eead4;
  border-radius: 12px;
  background: #12344f;
  color: #ffffff;
  font-weight: 850;
  cursor: pointer;
}
.performance-learning-headline {
  margin: 18px 0;
  font-size: 1.05rem;
  font-weight: 650;
}
.performance-learning-kpis {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 12px;
}
.performance-learning-kpis article {
  padding: 16px;
  border: 1px solid rgba(148, 163, 184, .24);
  border-radius: 16px;
  background: #0d2036;
  display: grid;
  gap: 7px;
}
.performance-learning-kpis strong {
  color: #ffffff;
  font-size: 1.45rem;
}
.performance-learning-grid {
  margin-top: 18px;
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(300px, .75fr);
  gap: 16px;
}
.performance-learning-grid > section,
.performance-learning-guidance {
  padding: 18px;
  border: 1px solid rgba(148, 163, 184, .22);
  border-radius: 18px;
  background: #0a192c;
}
.performance-learning-title {
  display: grid;
  gap: 4px;
  margin-bottom: 14px;
}
.performance-learning-title strong {
  color: #ffffff;
  font-size: 1.05rem;
}
.performance-learning-domains {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.performance-learning-domains article {
  padding: 14px;
  border: 1px solid rgba(94, 234, 212, .18);
  border-radius: 14px;
  background: #10243b;
}
.performance-learning-domains article > div {
  display: grid;
  gap: 3px;
}
.performance-learning-domains article > div strong {
  color: #ffffff;
  font-size: 1rem;
  text-transform: capitalize;
}
.performance-learning-domains dl {
  margin: 12px 0 0;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.performance-learning-domains dl div {
  display: grid;
  gap: 3px;
}
.performance-learning-domains dt {
  color: #9fb3c8;
  font-size: .77rem;
  font-weight: 750;
}
.performance-learning-domains dd {
  margin: 0;
  color: #ffffff;
  font-weight: 850;
}
.performance-learning-checks,
.performance-learning-guidance ul {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  gap: 9px;
}
.performance-learning-checks li {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 3px 10px;
  align-items: center;
  padding: 12px;
  border-radius: 12px;
  background: #10243b;
  border: 1px solid rgba(148, 163, 184, .18);
}
.performance-learning-checks li span {
  grid-row: span 2;
  min-width: 66px;
  padding: 6px 8px;
  border-radius: 999px;
  text-align: center;
  font-size: .75rem;
  font-weight: 900;
}
.performance-learning-checks li[data-status="passed"] span {
  background: rgba(45, 212, 191, .18);
  color: #99f6e4;
}
.performance-learning-checks li[data-status="pending"] span {
  background: rgba(251, 191, 36, .17);
  color: #fde68a;
}
.performance-learning-checks strong,
.performance-learning-guidance li {
  color: #f8fafc;
}
.performance-learning-checks small {
  color: #b8c7d8;
}
.performance-learning-guidance {
  margin-top: 16px;
}
.performance-learning-guidance li {
  padding: 11px 12px;
  border-left: 3px solid #5eead4;
  background: #10243b;
  border-radius: 8px;
}
@media (max-width: 1050px) {
  .performance-learning-kpis { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .performance-learning-grid { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
  .performance-learning-center { padding: 18px; }
  .performance-learning-header { grid-template-columns: 1fr; }
  .performance-learning-score { text-align: left; }
  .performance-learning-kpis,
  .performance-learning-domains { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .performance-learning-kpis,
  .performance-learning-domains { grid-template-columns: 1fr; }
}


/* V35.5.0 — Pilot-ready release gate */
